<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use App\Services\PeriodGuard;
class DormitoryController extends Controller{
private function view(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('dormitory_manager')||$r->user()->hasRole('upbringing_head')||$r->user()->canDo('dormitory.view')||$r->user()->canDo('dormitory.manage'),403);}
private function manage(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('dormitory_manager')||$r->user()->canDo('dormitory.manage'),403);}
public function index(Request $r){$this->view($r);$p=$r->attributes->get('academic_period');$stats=['buildings'=>DB::table('dormitory_buildings')->where('active',1)->count(),'places'=>DB::table('dormitory_places')->count(),'free'=>DB::table('dormitory_places')->where('status','available')->count(),'residents'=>DB::table('dormitory_stays')->where('status','active')->count(),'applications'=>DB::table('dormitory_applications')->where(['academic_period_id'=>$p->id,'status'=>'new'])->count(),'away'=>DB::table('dormitory_absences')->whereNull('returned_at')->count(),'incidents'=>DB::table('dormitory_incidents')->where(['academic_period_id'=>$p->id,'status'=>'open'])->count()];$buildings=DB::table('dormitory_buildings')->where('active',1)->get();return view('dormitory.index',compact('stats','buildings'));}
public function buildings(Request $r){$this->manage($r);$rows=DB::table('dormitory_buildings')->orderBy('name')->get();return view('dormitory.buildings',compact('rows'));}
public function buildingStore(Request $r){$this->manage($r);$d=$r->validate(['name'=>'required|string|max:255','address'=>'nullable|string|max:500','manager_name'=>'nullable|string|max:255','phone'=>'nullable|string|max:100']);DB::table('dormitory_buildings')->insert($d+['created_at'=>now(),'updated_at'=>now()]);return back();}
public function buildingUpdate(Request $r,$building){$this->manage($r);abort_unless(DB::table('dormitory_buildings')->where('id',$building)->exists(),404);$d=$r->validate(['name'=>'required|string|max:255','address'=>'nullable|string|max:500','manager_name'=>'nullable|string|max:255','phone'=>'nullable|string|max:100']);DB::table('dormitory_buildings')->where('id',$building)->update($d+['updated_at'=>now()]);return back()->with('success','Корпус обновлён');}
public function buildingDestroy(Request $r,$building){$this->manage($r);abort_unless(DB::table('dormitory_buildings')->where('id',$building)->exists(),404);$occupied=DB::table('dormitory_rooms as rm')->join('dormitory_places as p','p.dormitory_room_id','=','rm.id')->where('rm.dormitory_building_id',$building)->where('p.status','occupied')->exists();if($occupied)return back()->withErrors('Нельзя архивировать корпус, пока в нём есть проживающие.');DB::table('dormitory_buildings')->where('id',$building)->update(['active'=>0,'updated_at'=>now()]);return back()->with('success','Корпус архивирован');}
public function rooms(Request $r,$building){$this->view($r);$b=DB::table('dormitory_buildings')->find($building);abort_if(!$b,404);$rows=DB::table('dormitory_rooms as r')->where('r.dormitory_building_id',$building)->select('r.*',DB::raw("(select count(*) from dormitory_places p where p.dormitory_room_id=r.id) places"),DB::raw("(select count(*) from dormitory_places p where p.dormitory_room_id=r.id and p.status='available') free"))->orderBy('floor')->orderBy('number')->get();return view('dormitory.rooms',compact('b','rows'));}
public function roomStore(Request $r,$building){$this->manage($r);$d=$r->validate(['number'=>'required|string|max:50','floor'=>'nullable|integer|min:0','capacity'=>'required|integer|min:1|max:20','gender'=>'required|in:any,male,female']);$id=DB::transaction(function()use($d,$building){$id=DB::table('dormitory_rooms')->insertGetId($d+['dormitory_building_id'=>$building,'created_at'=>now(),'updated_at'=>now()]);for($i=1;$i<=$d['capacity'];$i++)DB::table('dormitory_places')->insert(['dormitory_room_id'=>$id,'number'=>(string)$i,'status'=>'available','created_at'=>now(),'updated_at'=>now()]);return $id;});return redirect()->route('dormitory.rooms',$building);}
public function roomUpdate(Request $r,$room){$this->manage($r);abort_unless(DB::table('dormitory_rooms')->where('id',$room)->exists(),404);$d=$r->validate(['number'=>'required|string|max:50','floor'=>'nullable|integer|min:0','gender'=>'required|in:any,male,female']);DB::table('dormitory_rooms')->where('id',$room)->update($d+['updated_at'=>now()]);return back()->with('success','Комната обновлена');}
public function residents(Request $r){$this->view($r);$rows=DB::table('dormitory_stays as st')->join('students as s','s.id','=','st.student_id')->join('dormitory_places as p','p.id','=','st.dormitory_place_id')->join('dormitory_rooms as rm','rm.id','=','p.dormitory_room_id')->join('dormitory_buildings as b','b.id','=','rm.dormitory_building_id')->where('st.status','active')->select('st.*','s.last_name','s.first_name','s.middle_name','b.name as building_name','rm.number as room_number','p.number as place_number')->orderBy('b.name')->orderBy('rm.number')->get();$freePlaces=DB::table('dormitory_places as p')->join('dormitory_rooms as rm','rm.id','=','p.dormitory_room_id')->join('dormitory_buildings as b','b.id','=','rm.dormitory_building_id')->where('p.status','available')->where('b.active',1)->select('p.id','p.number as place_number','rm.number as room_number','rm.gender','b.name as building_name')->orderBy('b.name')->orderBy('rm.number')->orderBy('p.number')->get();return view('dormitory.residents',compact('rows','freePlaces'));}
public function checkin(Request $r){$this->manage($r);$p=$r->attributes->get('academic_period');PeriodGuard::writable($p->id);$d=$r->validate(['student_id'=>'required|exists:students,id','dormitory_place_id'=>'required|exists:dormitory_places,id','check_in_on'=>'required|date','order_number'=>'nullable|string|max:100','order_date'=>'nullable|date','note'=>'nullable|string|max:3000']);DB::transaction(function()use($d,$p,$r){abort_if(DB::table('dormitory_stays')->where(['student_id'=>$d['student_id'],'status'=>'active'])->exists(),422,'Студент уже заселён');$place=DB::table('dormitory_places')->where('id',$d['dormitory_place_id'])->lockForUpdate()->first();abort_if(!$place||$place->status!=='available',422,'Место занято');DB::table('dormitory_stays')->insert($d+['academic_period_id'=>$p->id,'status'=>'active','created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);DB::table('dormitory_places')->where('id',$place->id)->update(['status'=>'occupied','updated_at'=>now()]);});return back();}
public function checkout(Request $r,$stay){$this->manage($r);$x=DB::table('dormitory_stays')->find($stay);abort_if(!$x||$x->status!=='active',404);$d=$r->validate(['check_out_on'=>'required|date','note'=>'nullable|string|max:3000']);DB::transaction(function()use($x,$d){DB::table('dormitory_stays')->where('id',$x->id)->update(['status'=>'closed','check_out_on'=>$d['check_out_on'],'note'=>$d['note']??$x->note,'updated_at'=>now()]);DB::table('dormitory_places')->where('id',$x->dormitory_place_id)->update(['status'=>'available','updated_at'=>now()]);});return back();}
public function applications(Request $r){$this->view($r);$p=$r->attributes->get('academic_period');$rows=DB::table('dormitory_applications as a')->join('students as s','s.id','=','a.student_id')->where('a.academic_period_id',$p->id)->select('a.*','s.last_name','s.first_name')->orderByRaw("case when a.status='new' then 0 else 1 end")->orderByDesc('a.priority')->orderBy('a.applied_on')->get();$students=DB::table('students')->where('status','active')->orderBy('last_name')->get();return view('dormitory.applications',compact('rows','students'));}
public function applicationStore(Request $r){$this->manage($r);$p=$r->attributes->get('academic_period');$d=$r->validate(['student_id'=>'required|exists:students,id','applied_on'=>'required|date','priority'=>'required|integer|min:0|max:100','reason'=>'nullable|string|max:3000']);DB::table('dormitory_applications')->insert($d+['academic_period_id'=>$p->id,'created_at'=>now(),'updated_at'=>now()]);return back();}
public function applicationDecision(Request $r,$id){$this->manage($r);$x=DB::table('dormitory_applications')->find($id);abort_if(!$x,404);$d=$r->validate(['status'=>'required|in:approved,rejected,waiting','decision'=>'nullable|string|max:3000']);DB::table('dormitory_applications')->where('id',$id)->update($d+['decided_by'=>$r->user()->id,'decided_at'=>now(),'updated_at'=>now()]);return back();}
public function roomCard(Request $r,$room){$this->view($r);$rm=DB::table('dormitory_rooms as r')->join('dormitory_buildings as b','b.id','=','r.dormitory_building_id')->where('r.id',$room)->select('r.*','b.name as building_name')->first();abort_if(!$rm,404);$residents=DB::table('dormitory_stays as st')->join('students as s','s.id','=','st.student_id')->join('dormitory_places as p','p.id','=','st.dormitory_place_id')->where('p.dormitory_room_id',$room)->where('st.status','active')->select('st.*','s.last_name','s.first_name','p.number as place_number')->get();$inspections=DB::table('dormitory_inspections')->where('dormitory_room_id',$room)->orderByDesc('inspected_at')->get();return view('dormitory.room-card',compact('rm','residents','inspections'));}
public function inspection(Request $r,$room){$this->manage($r);$d=$r->validate(['inspected_at'=>'required|date','condition'=>'required|in:good,attention,unsatisfactory','note'=>'nullable|string|max:5000','control_on'=>'nullable|date']);DB::table('dormitory_inspections')->insert($d+['dormitory_room_id'=>$room,'inspected_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return back();}
}